<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
$sponsorId=(int)($user['id']??0);
$hasAccess=sponsor_table_exists($conn,'sponsor_programme_access');
$hasContributions=sponsor_table_exists($conn,'sponsor_contributions');
$hasIndicators=sponsor_table_exists($conn,'sponsor_impact_indicators');
$hasBudgets=sponsor_table_exists($conn,'finance_budgets') && sponsor_table_exists($conn,'finance_expenditures');
$programmes=[];
if($hasAccess){
 $stmt=$conn->prepare("SELECT p.id,p.name,p.status,p.start_date,p.end_date,spa.assigned_at FROM sponsor_programme_access spa JOIN programmes p ON p.id=spa.programme_id WHERE spa.sponsor_user_id=? AND spa.access_status='active' ORDER BY p.name");
 if($stmt){$stmt->bind_param('i',$sponsorId);$stmt->execute();$res=$stmt->get_result();$programmes=$res?$res->fetch_all(MYSQLI_ASSOC):[];$stmt->close();}
}
$programmeIds=array_map(static fn($p)=>(int)$p['id'],$programmes);
$filterId=(int)($_GET['programme_id']??0);
if($filterId && !in_array($filterId,$programmeIds,true))$filterId=0;
$scopeIds=$filterId?[$filterId]:$programmeIds;
$in=$scopeIds?implode(',',array_map('intval',$scopeIds)):'0';
$money=static function(float $v):string{return 'R'.number_format($v,2);};
$received=0.0;$pledged=0.0;$inKind=0.0;$contributionRows=[];
if($hasContributions && $in!=='0'){
 $received=(float)(sponsor_rows($conn,"SELECT COALESCE(SUM(amount),0) total FROM sponsor_contributions WHERE sponsor_user_id={$sponsorId} AND programme_id IN ({$in}) AND contribution_status IN ('received','allocated') AND contribution_type='cash' AND currency='ZAR'")[0]['total']??0);
 $pledged=(float)(sponsor_rows($conn,"SELECT COALESCE(SUM(amount),0) total FROM sponsor_contributions WHERE sponsor_user_id={$sponsorId} AND programme_id IN ({$in}) AND contribution_status='pledged' AND contribution_type='cash' AND currency='ZAR'")[0]['total']??0);
 $inKind=(float)(sponsor_rows($conn,"SELECT COALESCE(SUM(amount),0) total FROM sponsor_contributions WHERE sponsor_user_id={$sponsorId} AND programme_id IN ({$in}) AND contribution_status IN ('received','allocated') AND contribution_type='in_kind' AND currency='ZAR'")[0]['total']??0);
 $contributionRows=sponsor_rows($conn,"SELECT sc.reference_no,sc.contribution_type,sc.contribution_status,sc.contribution_date,sc.amount,sc.currency,sc.description,p.name programme_name,c.name cohort_name FROM sponsor_contributions sc JOIN programmes p ON p.id=sc.programme_id LEFT JOIN cohorts c ON c.id=sc.cohort_id WHERE sc.sponsor_user_id={$sponsorId} AND sc.programme_id IN ({$in}) ORDER BY COALESCE(sc.contribution_date,DATE(sc.created_at)) DESC,sc.id DESC LIMIT 100");
}
$indicatorRows=[];$verifiedIndicators=0;$targetProgress=null;
if($hasIndicators && $in!=='0'){
 $indicatorRows=sponsor_rows($conn,"SELECT i.*,p.name programme_name,c.name cohort_name FROM sponsor_impact_indicators i JOIN programmes p ON p.id=i.programme_id LEFT JOIN cohorts c ON c.id=i.cohort_id WHERE i.sponsor_user_id={$sponsorId} AND i.programme_id IN ({$in}) ORDER BY FIELD(i.verification_status,'verified','pending','draft','rejected'),i.reporting_period_end DESC,i.id DESC LIMIT 150");
 $verifiedIndicators=count(array_filter($indicatorRows,static fn($r)=>$r['verification_status']==='verified'));
 $verified=sponsor_rows($conn,"SELECT COUNT(*) total, SUM(CASE WHEN target_value>0 THEN actual_value/target_value ELSE NULL END) progress FROM sponsor_impact_indicators WHERE sponsor_user_id={$sponsorId} AND programme_id IN ({$in}) AND verification_status='verified' AND actual_value IS NOT NULL");
 if(!empty($verified[0]['progress']))$targetProgress=(float)$verified[0]['progress'];
}
$participantCount=0;$completedParticipants=0;$placementCount=0;$completedPlacements=0;$cohortCount=0;$capacity=0;
if($in!=='0'){
 $r=sponsor_rows($conn,"SELECT COUNT(DISTINCT c.id) cohorts,COALESCE(SUM(c.max_capacity),0) capacity FROM cohorts c WHERE c.programme_id IN ({$in})");$cohortCount=(int)($r[0]['cohorts']??0);$capacity=(int)($r[0]['capacity']??0);
 $r=sponsor_rows($conn,"SELECT COUNT(DISTINCT cp.user_id) total,SUM(cp.status='completed') completed FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id WHERE c.programme_id IN ({$in}) AND cp.status<>'withdrawn'");$participantCount=(int)($r[0]['total']??0);$completedParticipants=(int)($r[0]['completed']??0);
 $r=sponsor_rows($conn,"SELECT COUNT(*) total,SUM(status='completed') completed FROM placements WHERE programme_id IN ({$in}) AND status NOT IN ('withdrawn','cancelled')");$placementCount=(int)($r[0]['total']??0);$completedPlacements=(int)($r[0]['completed']??0);
}
$budgetTotal=0.0;$paidSpend=0.0;$committedSpend=0.0;
if($hasBudgets && $in!=='0'){
 $r=sponsor_rows($conn,"SELECT COALESCE(SUM(allocated_amount),0) total FROM finance_budgets WHERE programme_id IN ({$in}) AND status='active'");$budgetTotal=(float)($r[0]['total']??0);
 $r=sponsor_rows($conn,"SELECT COALESCE(SUM(CASE WHEN e.status='paid' THEN e.amount ELSE 0 END),0) paid,COALESCE(SUM(CASE WHEN e.status='committed' THEN e.amount ELSE 0 END),0) committed FROM finance_expenditures e JOIN finance_budgets b ON b.id=e.budget_id WHERE b.programme_id IN ({$in}) AND b.status='active'");$paidSpend=(float)($r[0]['paid']??0);$committedSpend=(float)($r[0]['committed']??0);
}
$programmeSummary=[];
foreach($scopeIds as $pid){$pName='Programme';foreach($programmes as $p){if((int)$p['id']===$pid){$pName=$p['name'];break;}}
 $r=sponsor_rows($conn,"SELECT COUNT(DISTINCT c.id) cohorts,COALESCE(SUM(c.max_capacity),0) capacity FROM cohorts c WHERE c.programme_id={$pid}");
 $r2=sponsor_rows($conn,"SELECT COUNT(DISTINCT cp.user_id) participants FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id WHERE c.programme_id={$pid} AND cp.status<>'withdrawn'");
 $r3=sponsor_rows($conn,"SELECT COUNT(*) total,SUM(status='completed') completed FROM placements WHERE programme_id={$pid} AND status NOT IN ('withdrawn','cancelled')");
 $programmeSummary[]=['name'=>$pName,'cohorts'=>(int)($r[0]['cohorts']??0),'capacity'=>(int)($r[0]['capacity']??0),'participants'=>(int)($r2[0]['participants']??0),'placements'=>(int)($r3[0]['total']??0),'completed'=>(int)($r3[0]['completed']??0)];
}
sponsor_header('Sponsorship performance & impact','performance','Track your recorded contributions, programme delivery and verified beneficiary outcomes.');
?>
<style>
.sp-impact-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:18px 0 22px}.sp-impact-stat{padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--surface);min-width:0}.sp-impact-stat span{font-size:11px;color:var(--muted);font-weight:700}.sp-impact-stat strong{display:block;font-size:clamp(21px,2.3vw,29px);letter-spacing:-.04em;margin:8px 0 3px;overflow-wrap:anywhere}.sp-impact-stat small{color:var(--muted);font-size:10px}.sp-impact-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:16px}.sp-impact-note{border:1px solid var(--line);border-radius:13px;background:var(--surface2);padding:14px;color:var(--muted);font-size:12px;line-height:1.65}.sp-impact-filter{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:0 0 16px}.sp-impact-filter select{max-width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--text)}.sp-impact-bar{height:9px;background:var(--surface2);border-radius:20px;overflow:hidden;margin:7px 0 14px}.sp-impact-bar i{display:block;height:100%;background:linear-gradient(90deg,#4569e8,#16a77a);border-radius:20px}.sp-impact-empty{padding:22px;text-align:center;color:var(--muted);font-size:12px}.sp-table-small{font-size:11px!important}.sp-verified{color:var(--green)}.sp-pending{color:var(--amber)}@media(max-width:1000px){.sp-impact-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sp-impact-layout{grid-template-columns:1fr}}@media(max-width:520px){.sp-impact-grid{gap:8px}.sp-impact-stat{padding:13px}.sp-impact-stat strong{font-size:21px}}
</style>
<?php if(!$hasAccess): ?>
 <div class="sp-card"><div class="sp-cardbody"><div class="sp-impact-note"><strong>Setup required.</strong> Import <code>database/sponsor_performance_impact_migration.sql</code> before using this module. Programme access is deliberately restricted until an administrator assigns programmes to this sponsor account.</div></div></div>
<?php elseif(!$programmes): ?>
 <div class="sp-card"><div class="sp-cardhead"><div><h2>No funded programmes linked yet</h2><p>Your sponsor account has not been assigned programme access.</p></div></div><div class="sp-cardbody"><div class="sp-impact-note">Ask an authorised platform administrator to add your sponsor user ID and the relevant programme IDs to <code>sponsor_programme_access</code>. Once linked, this page will show only those programmes and their associated funding and impact records.</div></div></div>
<?php else: ?>
<form class="sp-impact-filter" method="get"><label for="programme_id" class="sp-muted">Programme scope</label><select id="programme_id" name="programme_id" onchange="this.form.submit()"><option value="0">All assigned programmes</option><?php foreach($programmes as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $filterId===(int)$p['id']?'selected':'' ?>><?= sponsor_e($p['name']) ?></option><?php endforeach; ?></select><a class="sp-btn" href="<?= url('sponsor/performance.php') ?>">Clear filter</a><a class="sp-btn primary" href="<?= url('sponsor/performance_export.php?programme_id='.$filterId) ?>">↓ Export report</a></form>
<section class="sp-impact-grid">
 <article class="sp-impact-stat"><span>Cash contributions received (ZAR)</span><strong><?= sponsor_e($money($received)) ?></strong><small>Confirmed received or allocated</small></article>
 <article class="sp-impact-stat"><span>Cash pledges outstanding (ZAR)</span><strong><?= sponsor_e($money($pledged)) ?></strong><small>Not yet recorded as received</small></article>
 <article class="sp-impact-stat"><span>In-kind support received (ZAR valuation)</span><strong><?= sponsor_e($money($inKind)) ?></strong><small>Recorded valuation; not cash</small></article>
 <article class="sp-impact-stat"><span>Beneficiaries participating</span><strong><?= number_format($participantCount) ?></strong><small>Distinct cohort participant records</small></article>
 <article class="sp-impact-stat"><span>Programme capacity</span><strong><?= number_format($capacity) ?></strong><small>Planned cohort capacity, not enrolment</small></article>
 <article class="sp-impact-stat"><span>Programme completions</span><strong><?= number_format($completedParticipants) ?></strong><small>Participant records marked completed</small></article>
 <article class="sp-impact-stat"><span>Placements recorded</span><strong><?= number_format($placementCount) ?></strong><small><?= number_format($completedPlacements) ?> explicitly completed</small></article>
 <article class="sp-impact-stat"><span>Verified impact indicators</span><strong><?= number_format($verifiedIndicators) ?></strong><small>Indicators with verified status</small></article>
</section>
<div class="sp-impact-layout">
 <section class="sp-card"><div class="sp-cardhead"><div><h2>Fund utilisation overview</h2><p>Finance budget ledger data for assigned programmes</p></div></div><div class="sp-cardbody">
 <?php if($hasBudgets): ?><div class="sp-report-grid"><div class="sp-report-item"><div class="sp-muted">Active programme budgets</div><div class="value"><?= sponsor_e($money($budgetTotal)) ?></div><p>Budget allocations in the finance ledger; not necessarily sponsor-only funds.</p></div><div class="sp-report-item"><div class="sp-muted">Paid expenditure</div><div class="value"><?= sponsor_e($money($paidSpend)) ?></div><p>Expenditures recorded with paid status.</p></div><div class="sp-report-item"><div class="sp-muted">Committed expenditure</div><div class="value"><?= sponsor_e($money($committedSpend)) ?></div><p>Expenditures recorded with committed status.</p></div><div class="sp-report-item"><div class="sp-muted">Remaining budget balance</div><div class="value"><?= sponsor_e($money($budgetTotal-$paidSpend-$committedSpend)) ?></div><p>Calculated as active budget less paid and committed spend.</p></div></div>
 <?php else: ?><div class="sp-impact-empty">Finance budget and expenditure tables are not installed. Funding contribution records are shown separately and are not treated as programme expenditure.</div><?php endif; ?>
 </div></section>
 <section class="sp-card"><div class="sp-cardhead"><div><h2>Beneficiary development</h2><p>Operational outcomes across assigned programmes</p></div></div><div class="sp-cardbody"><div class="sp-kpi-line"><span>Distinct participants</span><strong><?= number_format($participantCount) ?></strong></div><div class="sp-kpi-line"><span>Completed participants</span><strong><?= number_format($completedParticipants) ?></strong></div><div class="sp-kpi-line"><span>Placements recorded</span><strong><?= number_format($placementCount) ?></strong></div><div class="sp-kpi-line"><span>Completed placements</span><strong><?= number_format($completedPlacements) ?></strong></div><div class="sp-impact-note" style="margin-top:15px">Placement records indicate platform status only. They do not independently confirm employment duration, salary, job retention or employer satisfaction.</div></div></section>
</div>
<section class="sp-card"><div class="sp-cardhead"><div><h2>Programme delivery performance</h2><p>Participation and placement measures by assigned programme</p></div></div><div class="sp-tablewrap"><table><thead><tr><th>Programme</th><th>Cohorts</th><th>Planned capacity</th><th>Participants</th><th>Placements</th><th>Completed</th></tr></thead><tbody><?php foreach($programmeSummary as $r): ?><tr><td><strong><?= sponsor_e($r['name']) ?></strong></td><td><?= number_format($r['cohorts']) ?></td><td><?= number_format($r['capacity']) ?></td><td><?= number_format($r['participants']) ?></td><td><?= number_format($r['placements']) ?></td><td><?= number_format($r['completed']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="sp-card"><div class="sp-cardhead"><div><h2>Sponsorship contribution register</h2><p>Recorded commitments and contributions for your assigned programmes</p></div></div><?php if(!$hasContributions): ?><div class="sp-impact-empty">Contribution ledger not installed. Import the sponsorship performance migration and have Finance record verified contributions.</div><?php elseif(!$contributionRows): ?><div class="sp-impact-empty">No sponsorship contributions have been recorded for this programme scope.</div><?php else: ?><div class="sp-tablewrap"><table><thead><tr><th>Reference</th><th>Programme / cohort</th><th>Type</th><th>Status</th><th>Date</th><th>Amount</th></tr></thead><tbody><?php foreach($contributionRows as $r): ?><tr><td><strong><?= sponsor_e($r['reference_no']) ?></strong><div class="sp-muted"><?= sponsor_e($r['description']??'') ?></div></td><td><?= sponsor_e($r['programme_name']) ?><div class="sp-muted"><?= sponsor_e($r['cohort_name']??'All cohorts') ?></div></td><td><?= sponsor_e(ucwords(str_replace('_',' ',$r['contribution_type']))) ?></td><td><span class="sp-pill <?= sponsor_e($r['contribution_status']) ?>"><?= sponsor_e(ucwords($r['contribution_status'])) ?></span></td><td><?= sponsor_e(sponsor_date($r['contribution_date'])) ?></td><td><?= sponsor_e($r['currency']) ?> <?= number_format((float)$r['amount'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="sp-card"><div class="sp-cardhead"><div><h2>Impact indicators & outcomes</h2><p>Programme-level measures with evidence and verification status</p></div></div><?php if(!$hasIndicators): ?><div class="sp-impact-empty">Impact indicator register not installed. Import the sponsorship performance migration.</div><?php elseif(!$indicatorRows): ?><div class="sp-impact-empty">No impact indicators have been recorded yet. Verified results will appear here when programme teams submit evidence and an authorised reviewer verifies them.</div><?php else: ?><div class="sp-tablewrap"><table><thead><tr><th>Indicator</th><th>Programme / cohort</th><th>Baseline</th><th>Target</th><th>Actual</th><th>Period</th><th>Verification</th></tr></thead><tbody><?php foreach($indicatorRows as $r): ?><tr><td><strong><?= sponsor_e($r['indicator_name']) ?></strong><div class="sp-muted"><?= sponsor_e(ucwords(str_replace('_',' ',$r['indicator_category']))) ?> · <?= sponsor_e($r['unit']) ?></div><?php if(!empty($r['evidence_reference'])): ?><div class="sp-muted">Evidence: <?= sponsor_e($r['evidence_reference']) ?></div><?php endif; ?></td><td><?= sponsor_e($r['programme_name']) ?><div class="sp-muted"><?= sponsor_e($r['cohort_name']??'All cohorts') ?></div></td><td><?= $r['baseline_value']===null?'—':number_format((float)$r['baseline_value'],2).' '.sponsor_e($r['unit']) ?></td><td><?= $r['target_value']===null?'—':number_format((float)$r['target_value'],2).' '.sponsor_e($r['unit']) ?></td><td><?= $r['actual_value']===null?'—':number_format((float)$r['actual_value'],2).' '.sponsor_e($r['unit']) ?></td><td><?= sponsor_e(sponsor_date($r['reporting_period_start'])) ?> – <?= sponsor_e(sponsor_date($r['reporting_period_end'])) ?></td><td><span class="<?= $r['verification_status']==='verified'?'sp-verified':'sp-pending' ?>"><?= sponsor_e(ucwords($r['verification_status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<div class="sp-impact-note"><strong>Reporting and assurance.</strong> Financial contribution records, programme budgets and expenditures are separate ledgers and must not be added together as though they were the same measure. Programme budget totals may include non-sponsor funding. In-kind values are reported separately from cash. Only verified impact indicators count as verified impact. Participant, completion and placement totals are operational platform records, not independently audited outcomes. No personal contact details are exposed in this report.</div>
<?php endif; ?>
<?php sponsor_footer(); ?>
